            .dyn_into::<web_sys::DedicatedWorkerGlobalScope>()
            .map_err(|_| Error::Forbidden)?;
        if transport::validate_app_origin(&worker.location().origin())?
            != transport::validate_app_origin(app_origin)?
        {
            return Err(Error::Forbidden);
        }
