impl Client {
    pub fn set_foreground_completion_recovery(&mut self, enabled: bool) -> Result<()> {
        if !enabled {
            if let Some(mode) = self.completion_recovery_mode.take() {
                mode.cancel()
            }
            self.completion_recovery_jobs.clear();
            self.metadata_recovery_jobs.clear();
            return Ok(());
        }
        self.require_canonical_read_profile()?;
        if self
            .completion_recovery_mode
            .as_ref()
            .is_none_or(CancellationToken::is_cancelled)
        {
            self.completion_recovery_mode = Some(CancellationToken::new())
        }
        Ok(())
    }
    fn recovery_fence(&self, cancel: &CancellationToken) -> Result<RecoveryFence> {
        self.require_canonical_read_profile()?;
        let session = self.require_credentials()?;
        let mode = self
            .completion_recovery_mode
            .as_ref()
            .filter(|token| !token.is_cancelled())
            .ok_or(Error::Unavailable {
                code: "completion_recovery_unavailable",
                reason: "COMPLETION_RECOVERY_REQUIRES_EXPLICIT_FOREGROUND",
            })?;
        let fence = RecoveryFence {
            authority: self.task_watch_authority.clone(),
            mode: mode.clone(),
            caller: cancel.clone(),
            operation: self.operation_cancel.clone(),
            expires_at: session.paired_session_expires_at,
            lease_expires_at: None,
            master: self.master_capability()?,
            binding: Arc::new(self.master_binding()?),
            credential_context: recovery_credential_context(self)?,
        };
        fence.check_client(self)?;
        Ok(fence)
    }
    fn check_recovery_owner(
        &self,
        checkpoint: &CompletionRecoveryCheckpoint,
        fence: &RecoveryFence,
    ) -> Result<()> {
        fence.check_client(self)?;
        if !Arc::ptr_eq(&fence.authority, &self.task_watch_authority)
            || self
                .completion_recovery_mode
                .as_ref()
                .is_none_or(CancellationToken::is_cancelled)
        {
            return Err(Error::Cancelled);
        }
        if checkpoint.protocol_version != 1
            || checkpoint.api_url != self.base.as_str().trim_end_matches('/')
            || checkpoint.owner_id != owner(self)?
            || checkpoint.team_id.as_deref() != self.team()?
        {
            return Err(Error::Forbidden);
        }
        Ok(())
    }
    pub async fn completion_recovery_jobs(
        &mut self,
        cancel: &CancellationToken,
    ) -> Result<Vec<CompletionRecoveryJob>> {
        self.discover_completion_recovery(cancel, false)
            .await
            .map(|(jobs, _)| jobs)
    }
    /// Discover recovery work and retain optional proof of the same fully
    /// completed fresh sync. Partial discovery still returns jobs, never proof.
    /// Keep this opaque value in memory; persist credentials/ciphertext through
    /// the caller's existing durability contract before publishing private output.
    pub async fn completion_recovery_jobs_with_inventory(
        &mut self,
        cancel: &CancellationToken,
    ) -> Result<(Vec<CompletionRecoveryJob>, Option<FreshChatInventory>)> {
        let (jobs, complete) = self.discover_completion_recovery(cancel, true).await?;
        let inventory = if complete {
            self.fresh_chat_inventory(cancel)?
        } else {
            None
        };
        Ok((jobs, inventory))
    }
    async fn discover_completion_recovery(
        &mut self,
        cancel: &CancellationToken,
        inventory: bool,
    ) -> Result<(Vec<CompletionRecoveryJob>, bool)> {
        let fence = self.recovery_fence(cancel)?;
        self.completion_recovery_jobs.clear();
        self.metadata_recovery_jobs.clear();
        let refresh = async {
            if inventory {
                self.refresh_chat_metadata_for_inventory().await
            } else {
                self.refresh_chat_metadata(0).await.map(|_| false)
            }
        };
        let complete = match fence.run(refresh).await {
            Ok(complete) => complete,
            Err(Error::Offline | Error::Conflict | Error::Protocol)
                if !self.completion_recovery_jobs.is_empty() =>
            {
                // The sync transaction already published fenced job discovery.
                // An independently durable typed-output replay can be deferred
                // until main persistence; it must not hide the only main job.
                false
            }
            Err(error) => return Err(error),
        };
        fence.check_client(self)?;
        let personal = self.team()?.is_none();
        let jobs = self
            .completion_recovery_jobs
            .values()
            .chain(self.metadata_recovery_jobs.values().filter(|_| personal))
            .cloned()
            .collect();
        fence.check_client(self)?;
        Ok((jobs, complete))
    }
    async fn recovery_current_key(
        &mut self,
        id: &str,
        fence: &RecoveryFence,
    ) -> Result<(Value, Key)> {
        canonical_uuid(id)?;
        let scope = AsyncCryptoScope::begin(self)?;
        scope.check_chat(self, id)?;
        fence.check_client(self)?;
        let metadata = fence
            .run(self.request_chat_metadata(id))
            .await?
            .ok_or(Error::Forbidden)?;
        scope.check_chat(self, id)?;
        fence.check_client(self)?;
        let row = metadata["chats"]
            .as_array()
            .ok_or(Error::Protocol)?
            .iter()
            .find(|row| text(row, "id") == id)
            .ok_or(Error::Forbidden)?
            .clone();
        let team = self.team()?.map(str::to_owned);
        validate_selected_team_recovery_wrapper(&row, id, team.as_deref())?;
        let mut selected_wrapper = None;
        let key = if text(&row, "chat_visibility") == "direct" {
            self.native_master_key()?;
            fence.run(self.load_direct_identity()).await?;
            scope.check_chat(self, id)?;
            fence.check_client(self)?;
            self.direct_chat_key(&row)?
        } else {
            let master = self.master_capability()?;
            let wrapping = if let Some(team) = &team {
                let response = fence
                    .run(self.request(Method::GET, &format!("/v1/teams/{}", segment(team)), None))
                    .await?;
                scope.check_chat(self, id)?;
                fence.check_client(self)?;
                if response["team"]["team_id"] != *team {
                    return Err(Error::Forbidden);
                }
                let encrypted = required(&response["team"], "encrypted_team_key")?.to_owned();
                let bytes = fence.run(master.decrypt_bytes(&encrypted)).await?;
                scope.check_chat(self, id)?;
                fence.check_client(self)?;
                let key = key_from_bytes(&bytes)?;
                self.team_key = Some((team.clone(), key.clone()));
                self.team_wrapped_key = Some((team.clone(), encrypted));
                MasterCapability::from_native(key)
            } else {
                master
            };
            if team.as_ref().is_some_and(|team| {
                row["hashed_team_id"]
                    .as_str()
                    .is_some_and(|hash| hash != sha256(team))
                    || row["team_id"].as_str().is_some_and(|id| id != team)
            }) || team.is_none()
                && (row["hashed_team_id"]
                    .as_str()
                    .is_some_and(|value| !value.is_empty())
                    || row["team_id"]
                        .as_str()
                        .is_some_and(|value| !value.is_empty()))
            {
                return Err(Error::Forbidden);
            }
            let wrappers = row["chat_key_wrappers"]
                .as_array()
                .into_iter()
                .flatten()
                .filter(|wrapper| {
                    text(wrapper, "hashed_chat_id") == sha256(id)
                        && text(wrapper, "key_type")
                            == if team.is_some() { "team" } else { "master" }
                        && team
                            .as_ref()
                            .is_none_or(|team| text(wrapper, "hashed_team_id") == sha256(team))
                })
                .collect::<Vec<_>>();
            let encrypted = match wrappers.as_slice() {
                [wrapper] => {
                    validate_recovery_wrapper(wrapper, team.is_some(), now_ms())?;
                    selected_wrapper = Some(*wrapper);
                    required(wrapper, "encrypted_chat_key")?
                }
                [] if team.is_none() => required(&row, "encrypted_chat_key")?,
                _ => return Err(Error::Forbidden),
            };
            match selected_wrapper {
                Some(wrapper) => {
                    self.recovery_unwrap_selected_key(
                        encrypted,
                        &wrapping,
                        fence,
                        &scope,
                        id,
                        wrapper,
                        team.is_some(),
                    )
                    .await?
                }
                None => {
                    self.recovery_unwrap_key(encrypted, &wrapping, fence, &scope, id)
                        .await?
                }
            }
        };
        scope.check_chat(self, id)?;
        fence.check_client(self)?;
        // The selected wrapper can expire during platform AES. Recheck the
        // same row at the final synchronous cache publication boundary too.
        if let Some(wrapper) = selected_wrapper {
            validate_recovery_wrapper(wrapper, team.is_some(), now_ms())?;
        }
        self.wrappers
            .retain(|wrapper| text(wrapper, "hashed_chat_id") != sha256(id));
        self.wrappers.extend(
            row["chat_key_wrappers"]
                .as_array()
                .into_iter()
                .flatten()
                .cloned(),
        );
        self.insert_chat_row(id.to_owned(), row.clone());
        Ok((row, key))
    }
    async fn recovery_unwrap_key(
        &self,
        encrypted: &str,
        wrapping: &MasterCapability,
        fence: &RecoveryFence,
        scope: &AsyncCryptoScope,
        id: &str,
    ) -> Result<Key> {
        scope.check_chat(self, id)?;
        fence.check_client(self)?;
        let bytes = fence.run(wrapping.decrypt_bytes(encrypted)).await?;
        scope.check_chat(self, id)?;
        fence.check_client(self)?;
        key_from_bytes(&bytes)
    }
    #[allow(clippy::too_many_arguments)]
    async fn recovery_unwrap_selected_key(
        &self,
        encrypted: &str,
        wrapping: &MasterCapability,
        fence: &RecoveryFence,
        scope: &AsyncCryptoScope,
        id: &str,
        wrapper: &Value,
        team: bool,
    ) -> Result<Key> {
        validate_recovery_wrapper(wrapper, team, now_ms())?;
        let key = self
            .recovery_unwrap_key(encrypted, wrapping, fence, scope, id)
            .await?;
        // Key is Zeroizing: expiry/conflict discards authenticated bytes before
        // the caller may publish/cache or build a stage from them.
        validate_recovery_wrapper(wrapper, team, now_ms())?;
        scope.check_chat(self, id)?;
        fence.check_client(self)?;
        Ok(key)
    }
    async fn recovery_exchange(
        &mut self,
        ws: &mut Socket,
        kind: &str,
        mut payload: Value,
        reply: &str,
        job_id: &str,
        fence: &RecoveryFence,
    ) -> Result<Value> {
        let scope = AsyncCryptoScope::begin(self)?;
        scope.check(self)?;
        fence.check_client(self)?;
        let request_id = uuid::Uuid::new_v4().to_string();
        payload["protocol_version"] = json!(1);
        payload["job_id"] = json!(job_id);
        payload["request_id"] = json!(request_id);
        fence
            .run(async {
                scope.check(self)?;
                fence.check_client(self)?;
                send(ws, kind, payload).await?;
                scope.check(self)?;
                fence.check_client(self)?;
                for _ in 0..1000 {
                    let (received, value) = receive_ephemeral(ws).await?;
                    scope.check(self)?;
                    fence.check_client(self)?;
                    if value["request_id"] == request_id && value["job_id"] == job_id {
                        if received == reply {
                            return Ok(value);
                        }
                        if received == "error" {
                            return Err(match value["code"].as_str() {
                                Some(
                                    "lease_conflict"
                                    | "stale_lease"
                                    | "lease_tenure_exhausted"
                                    | "version_conflict",
                                ) => Error::Conflict,
                                Some(
                                    "recovery_job_not_found"
                                    | "metadata_job_not_found"
                                    | "recovery_requires_foreground",
                                ) => Error::Forbidden,
                                _ => Error::Protocol,
                            });
                        }
                    }
                    capture(
                        &received,
                        &value,
                        &mut self.completion_recovery_jobs,
                        &mut self.metadata_recovery_jobs,
                    )?;
                }
                Err(Error::Protocol)
            })
            .await
    }
    async fn recovery_foreground_socket(&mut self, fence: &RecoveryFence) -> Result<Socket> {
        let scope = AsyncCryptoScope::begin(self)?;
        scope.check(self)?;
        fence.check_client(self)?;
        let mut ws = fence.run(self.completion_recovery_socket()).await?;
        scope.check(self)?;
        fence.check_client(self)?;
        fence
            .run(async {
                for _ in 0..1000 {
                    let (kind, payload) = receive_ephemeral(&mut ws).await?;
                    scope.check(self)?;
                    fence.check_client(self)?;
                    if kind == "native_client_lifecycle_ack" {
                        if payload["is_foreground"] != true {
                            return Err(Error::Forbidden);
                        }
                        return Ok(());
                    }
                    capture(
                        &kind,
                        &payload,
                        &mut self.completion_recovery_jobs,
                        &mut self.metadata_recovery_jobs,
                    )?;
                }
                Err(Error::Protocol)
            })
            .await?;
        scope.check(self)?;
        fence.check_client(self)?;
        Ok(ws)
    }
    async fn reconcile_main(
        &mut self,
        job: &CompletionRecoveryJob,
        key: &[u8; 32],
        fence: &RecoveryFence,
    ) -> Result<Option<CompletionRecoveryReceipt>> {
        let scope = AsyncCryptoScope::begin(self)?;
        scope.check_chat(self, &job.chat_id)?;
        fence.check_client(self)?;
        let chat = fence.run_plain(self.open_chat_live(&job.chat_id)).await?;
        scope.check_chat(self, &job.chat_id)?;
        fence.check_client(self)?;
        // open_chat_live freshly resolves wrappers again. A changed key may not
        // validate a checkpoint produced under the earlier current-key lookup.
        let row = self.chats.get(&job.chat_id).ok_or(Error::Protocol)?;
        let wrapping = self.cached_wrapping_capability()?;
        let current_key = fence
            .run(self.chat_key_with_capability(row, &wrapping))
            .await?;
        scope.check_chat(self, &job.chat_id)?;
        fence.check_client(self)?;
        if current_key.as_ref() != key {
            return Err(Error::Crypto);
        }
        let expected = job.assistant_message_id.as_deref().ok_or(Error::Protocol)?;
        let matching = chat
            .messages
            .iter()
            .filter(|message| message.id == expected)
            .collect::<Vec<_>>();
        if matching.is_empty() {
            return Ok(None);
        }
        if matching.len() != 1 || matching[0].role != "assistant" {
            return Err(Error::Protocol);
        }
        Ok(Some(CompletionRecoveryReceipt {
            job_id: job.job_id.clone(),
            chat_id: job.chat_id.clone(),
            assistant_message_id: Some(expected.into()),
            messages_version: Some(
                row["messages_v"]
                    .as_u64()
                    .filter(|v| *v > 0)
                    .ok_or(Error::Protocol)?,
            ),
            metadata_version: None,
            title_version: None,
            state: "TERMINAL".into(),
        }))
    }
    fn canonical_main_candidate(&self, job: &CompletionRecoveryJob) -> Result<Option<Value>> {
        let expected = job.assistant_message_id.as_deref().ok_or(Error::Protocol)?;
        let rows = self
            .history
            .get(&job.chat_id)
            .into_iter()
            .flatten()
            .filter(|row| {
                ["client_message_id", "message_id", "id"]
                    .iter()
                    .find_map(|field| row[*field].as_str().filter(|id| !id.is_empty()))
                    == Some(expected)
            })
            .collect::<Vec<_>>();
        let raw = match rows.as_slice() {
            [] => return Ok(None),
            [row] => *row,
            _ => return Err(Error::Protocol),
        };
        if raw["role"] != "assistant" {
            return Err(Error::Protocol);
        }
        let mut candidate =
            json!({"client_message_id":expected,"chat_id":job.chat_id,"role":"assistant"});
        for field in [
            "encrypted_content",
            "encrypted_sender_name",
            "created_at",
            "updated_at",
            "encrypted_category",
            "encrypted_model_name",
            "encrypted_thinking_content",
            "encrypted_thinking_signature",
        ] {
            if let Some(value) = raw.get(field).filter(|value| !value.is_null()) {
                candidate[field] = value.clone();
            }
        }
        Ok(Some(candidate))
    }
    pub async fn stage_completion_recovery(
        &mut self,
        job: &CompletionRecoveryJob,
        cancel: &CancellationToken,
    ) -> Result<CompletionRecoveryAdmission> {
        self.stage_recovery(job, None, cancel).await
    }
    pub async fn resume_completion_recovery(
        &mut self,
        checkpoint: CompletionRecoveryCheckpoint,
        cancel: &CancellationToken,
    ) -> Result<CompletionRecoveryAdmission> {
        // Stored DTO is only ciphertext/data. Its identity is rechecked against
        // fresh explicit credentials and canonical state before a claim/send.
        let job = checkpoint.job.clone();
        self.stage_recovery(&job, Some(checkpoint), cancel).await
    }
    async fn stage_recovery(
        &mut self,
        job: &CompletionRecoveryJob,
        saved: Option<CompletionRecoveryCheckpoint>,
        cancel: &CancellationToken,
    ) -> Result<CompletionRecoveryAdmission> {
        let mut fence = self.recovery_fence(cancel)?;
        validate_job(job)?;
        fence.run(self.validate_session()).await?;
        fence.check_client(self)?;
        let scope = AsyncCryptoScope::begin(self)?;
        scope.check_chat(self, &job.chat_id)?;
        canonical_uuid(&job.job_id)?;
        canonical_uuid(&job.chat_id)?;
        if job.chat_key_version != 1 {
            return Ok(CompletionRecoveryAdmission::Deferred);
        }
        if job.kind == CompletionRecoveryKind::Metadata && self.team()?.is_some() {
            return Ok(CompletionRecoveryAdmission::Deferred);
        }
        if let Some(saved) = &saved {
            self.check_recovery_owner(saved, &fence)?;
            if serde_json::to_value(&saved.job)? != serde_json::to_value(job)? {
                return Err(Error::Protocol);
            }
        }
        let (row, key) = match self.recovery_current_key(&job.chat_id, &fence).await {
            Err(Error::Conflict) => return Ok(CompletionRecoveryAdmission::Deferred),
            result => result?,
        };
        // Reconcile exact canonical assistant before claim, but only a later
        // authoritative TERMINAL claim can declare this job already finished.
        let canonical = if job.kind == CompletionRecoveryKind::Main {
            self.reconcile_main(job, &key, &fence).await?
        } else {
            None
        };
        if let Some(saved) = &saved {
            if saved.canonical_ciphertext
                && self.canonical_main_candidate(job)?.as_ref() != Some(&saved.encrypted_candidate)
            {
                return Ok(CompletionRecoveryAdmission::Deferred);
            }
            validate_checkpoint_candidate(saved, &key, None)?;
        }
        scope.check_chat(self, &job.chat_id)?;
        let mut ws = self.recovery_foreground_socket(&fence).await?;
        scope.check_chat(self, &job.chat_id)?;
        let (claim_kind, claim_reply) = if job.kind == CompletionRecoveryKind::Main {
            ("recovery_job_claim", "recovery_job_claimed")
        } else {
            ("metadata_job_claim", "metadata_job_claimed")
        };
        let claim = match self
            .recovery_exchange(
                &mut ws,
                claim_kind,
                json!({}),
                claim_reply,
                &job.job_id,
                &fence,
            )
            .await
        {
            Err(Error::Conflict) => return Ok(CompletionRecoveryAdmission::Deferred),
            result => result?,
        };
        scope.check_chat(self, &job.chat_id)?;
        same_job(job, &claim)?;
        if matches!(claim["state"].as_str(), Some("TERMINAL" | "SUPERSEDED")) {
            if job.kind == CompletionRecoveryKind::Main {
                let receipt = match canonical {
                    Some(receipt) => receipt,
                    None => self
                        .reconcile_main(job, &key, &fence)
                        .await?
                        .ok_or(Error::Protocol)?,
                };
                scope.check_chat(self, &job.chat_id)?;
                fence.check_client(self)?;
                return Ok(CompletionRecoveryAdmission::Canonical(receipt));
            }
            let (current, _) = self.recovery_current_key(&job.chat_id, &fence).await?;
            scope.check_chat(self, &job.chat_id)?;
            fence.check_client(self)?;
            return Ok(CompletionRecoveryAdmission::Canonical(metadata_receipt(
                job, &claim, &current,
            )?));
        }
        let encrypted_candidate;
        let wrapped_chat_key;
        let (lease_token, lease_generation) = if job.kind == CompletionRecoveryKind::Main {
            if claim["state"] != "LEASED" {
                return Err(Error::Protocol);
            }
            let token = required(&claim, "lease_token")?;
            if token.len() > 128 || token.chars().any(char::is_control) {
                return Err(Error::Protocol);
            }
            let generation = claim["lease_generation"]
                .as_u64()
                .filter(|v| *v > 0)
                .ok_or(Error::Protocol)?;
            fence.lease_expires_at = Some(iso_timestamp_ms(required(&claim, "lease_expires_at")?)?);
            fence.check_client(self)?;
            let identity = main_identity(&owner(self)?, job)?;
            let envelope: Value = serde_json::from_str(required(&claim, "sealed_payload")?)?;
            let recovered = Plain::new(decode_main_completion(&envelope, &key, &identity)?);
            fence.check_client(self)?;
            encrypted_candidate = if canonical.is_some() {
                let candidate = match self.canonical_main_candidate(job)? {
                    Some(candidate) => candidate,
                    None => return Ok(CompletionRecoveryAdmission::Deferred),
                };
                let probe = CompletionRecoveryCheckpoint {
                    protocol_version: 1,
                    api_url: self.base.as_str().trim_end_matches('/').into(),
                    owner_id: owner(self)?,
                    team_id: self.team()?.map(str::to_owned),
                    job: job.clone(),
                    encrypted_candidate: candidate.clone(),
                    wrapped_chat_key: None,
                    canonical_ciphertext: true,
                };
                if validate_checkpoint_candidate(&probe, &key, Some(&recovered)).is_err() {
                    return Ok(CompletionRecoveryAdmission::Deferred);
                }
                if let Some(saved) = &saved {
                    validate_checkpoint_candidate(saved, &key, Some(&recovered))?;
                    if saved.encrypted_candidate != candidate {
                        return Err(Error::Conflict);
                    }
                }
                candidate
            } else if let Some(saved) = &saved {
                validate_checkpoint_candidate(saved, &key, Some(&recovered))?;
                saved.encrypted_candidate.clone()
            } else {
                encrypt_main_assistant(&recovered, &identity, now_ms() / 1000, None, &key)?
            };
            wrapped_chat_key = None;
            (
                Some(zeroize::Zeroizing::new(token.into())),
                Some(generation),
            )
        } else {
            if claim["state"] != "AVAILABLE" {
                return Err(Error::Protocol);
            }
            let recovered = Plain::new(decode_metadata_completion(
                &claim,
                &owner(self)?,
                job,
                &key,
            )?);
            fence.check_client(self)?;
            encrypted_candidate = if let Some(saved) = &saved {
                validate_checkpoint_candidate(saved, &key, Some(&recovered))?;
                saved.encrypted_candidate.clone()
            } else {
                encrypt_metadata_fields(&recovered, &key)?
            };
            wrapped_chat_key = Some(required(&row, "encrypted_chat_key")?.to_owned());
            if saved
                .as_ref()
                .is_some_and(|saved| saved.wrapped_chat_key != wrapped_chat_key)
            {
                return Err(Error::Crypto);
            }
            (None, None)
        };
        let checkpoint = CompletionRecoveryCheckpoint {
            protocol_version: 1,
            api_url: self.base.as_str().trim_end_matches('/').into(),
            owner_id: owner(self)?,
            team_id: self.team()?.map(str::to_owned),
            job: job.clone(),
            encrypted_candidate,
            wrapped_chat_key,
            canonical_ciphertext: saved
                .as_ref()
                .map_or(canonical.is_some(), |saved| saved.canonical_ciphertext),
        };
        scope.check_chat(self, &job.chat_id)?;
        self.check_recovery_owner(&checkpoint, &fence)?;
        // Stage continuation survives routine per-call child replacement.
        // Retain the explicit caller/mode/owner lifetime, while each awaited
        // operation used and commit will use its own current Client child.
        fence.operation = cancel.clone();
        Ok(CompletionRecoveryAdmission::Ready(Box::new(
            CompletionRecoveryStage {
                socket: ws,
                checkpoint,
                key,
                fence,
                lease_token,
                lease_generation,
                canonical_settlement: canonical.is_some(),
            },
        )))
    }
    pub async fn commit_completion_recovery(
        &mut self,
        mut stage: CompletionRecoveryStage,
        durable: CompletionRecoveryDurableReceipt,
        cancel: &CancellationToken,
    ) -> Result<CompletionRecoveryReceipt> {
        self.check_recovery_owner(&stage.checkpoint, &stage.fence)?;
        if cancel.is_cancelled() {
            return Err(Error::Cancelled);
        }
        if durable.checkpoint_sha256 != stage.checkpoint.digest()? {
            return Err(Error::Conflict);
        }
        let fresh = self.recovery_fence(cancel)?;
        fresh.run(self.validate_session()).await?;
        fresh.check_client(self)?;
        let scope = AsyncCryptoScope::begin(self)?;
        scope.check_chat(self, &stage.checkpoint.job.chat_id)?;
        self.check_recovery_owner(&stage.checkpoint, &stage.fence)?;
        let job = stage.checkpoint.job.clone();
        let (row, key) = fresh
            .run(self.recovery_current_key(&job.chat_id, &stage.fence))
            .await?;
        if key.as_ref() != stage.key.as_ref() {
            return Err(Error::Crypto);
        }
        validate_checkpoint_candidate(&stage.checkpoint, &key, None)?;
        if job.kind == CompletionRecoveryKind::Main {
            // Reconcile before any re-persist, including a concurrent winner or
            // the caller's resume after an ambiguous previous ACK.
            let existing = fresh
                .run(self.reconcile_main(&job, &key, &stage.fence))
                .await?;
            if stage.canonical_settlement
                || (existing.is_some()
                    && self.canonical_main_candidate(&job)?.as_ref()
                        == Some(&stage.checkpoint.encrypted_candidate))
            {
                if existing.is_none()
                    || self.canonical_main_candidate(&job)?.as_ref()
                        != Some(&stage.checkpoint.encrypted_candidate)
                {
                    return Err(Error::Conflict);
                }
            } else if let Some(receipt) = existing {
                let state = fresh
                    .run(self.recovery_exchange(
                        &mut stage.socket,
                        "recovery_job_claim",
                        json!({}),
                        "recovery_job_claimed",
                        &job.job_id,
                        &stage.fence,
                    ))
                    .await?;
                same_job(&job, &state)?;
                if state["state"] != "TERMINAL" {
                    return Err(Error::Conflict);
                }
                scope.check_chat(self, &job.chat_id)?;
                stage.fence.check_client(self)?;
                return Ok(receipt);
            }
            let payload = json!({"lease_token":stage.lease_token.as_ref().ok_or(Error::Protocol)?.as_str(),"lease_generation":stage.lease_generation.ok_or(Error::Protocol)?,"expected_messages_v":row["messages_v"].as_u64().ok_or(Error::Protocol)?,"encrypted_assistant_message":stage.checkpoint.encrypted_candidate});
            let receipt = fresh
                .run(self.recovery_exchange(
                    &mut stage.socket,
                    "recovery_job_persist",
                    payload,
                    "recovery_job_persisted",
                    &job.job_id,
                    &stage.fence,
                ))
                .await?;
            if receipt["state"] != "TERMINAL" {
                return Err(Error::Protocol);
            }
            let result = fresh
                .run(self.reconcile_main(&job, &key, &stage.fence))
                .await?
                .ok_or(Error::Protocol)?;
            scope.check_chat(self, &job.chat_id)?;
            stage.fence.check_client(self)?;
            return Ok(result);
        }
        if self.team()?.is_some()
            || Some(required(&row, "encrypted_chat_key")?)
                != stage.checkpoint.wrapped_chat_key.as_deref()
        {
            return Err(Error::Forbidden);
        }
        let payload = json!({"chat_key_version":1,"wrapped_chat_key":stage.checkpoint.wrapped_chat_key,"encrypted_metadata":stage.checkpoint.encrypted_candidate});
        let receipt = fresh
            .run(self.recovery_exchange(
                &mut stage.socket,
                "metadata_job_persist",
                payload,
                "metadata_job_persisted",
                &job.job_id,
                &stage.fence,
            ))
            .await?;
        same_job(&job, &receipt)?;
        if !matches!(receipt["state"].as_str(), Some("TERMINAL" | "SUPERSEDED")) {
            return Err(Error::Protocol);
        }
        let (current, _) = fresh
            .run(self.recovery_current_key(&job.chat_id, &stage.fence))
            .await?;
        let updated = merge_metadata_receipt(&receipt, &current)?;
        let result = metadata_receipt(&job, &receipt, &updated)?;
        scope.check_chat(self, &job.chat_id)?;
        stage.fence.check_client(self)?;
        self.insert_chat_row(job.chat_id.clone(), updated);
        Ok(result)
    }
}
fn main_identity(owner: &str, job: &CompletionRecoveryJob) -> Result<crypto::RecoveryIdentity> {
    Ok(crypto::RecoveryIdentity {
        owner_id: owner.into(),
        chat_id: job.chat_id.clone(),
        turn_id: job.turn_id.clone().ok_or(Error::Protocol)?,
        job_id: job.job_id.clone(),
        assistant_message_id: job.assistant_message_id.clone().ok_or(Error::Protocol)?,
        key_version: job.chat_key_version,
    })
}
pub(super) fn decode_main_completion(
    envelope: &Value,
    key: &[u8; 32],
    identity: &crypto::RecoveryIdentity,
) -> Result<Value> {
    let pair = crypto::recovery_keypair(key, &identity.chat_id, identity.key_version)?;
    let plain = crypto::open_recovery_envelope(envelope, &pair.private_key, identity)?;
    let recovered: Value = serde_json::from_slice(&plain)?;
    let recovered =
        admit_recovery_plain(recovered, |value| validate_main_plaintext(value, identity))?;
    Ok(recovered.into_inner())
}
// The guard is installed before validation so well-formed but rejected
// decrypted JSON (including nested strings) is wiped on every error path.
fn admit_recovery_plain<T: super::plaintext::Wipe>(
    value: T,
    validate: impl FnOnce(&T) -> Result<()>,
) -> Result<Plain<T>> {
    let value = Plain::new(value);
    validate(&value)?;
    Ok(value)
}
fn validate_main_plaintext(value: &Value, identity: &crypto::RecoveryIdentity) -> Result<()> {
    let object = value.as_object().ok_or(Error::Protocol)?;
    let required_fields = [
        "assistant_message_id",
        "category",
        "chat_id",
        "content",
        "job_id",
        "key_version",
        "model_name",
        "turn_id",
    ];
    let optional = [
        "thinking_content",
        "thinking_signature",
        "has_thinking",
        "thinking_token_count",
        "thinking_duration_seconds",
    ];
    if required_fields
        .iter()
        .any(|field| !object.contains_key(*field))
        || object.keys().any(|field| {
            !required_fields.contains(&field.as_str()) && !optional.contains(&field.as_str())
        })
    {
        return Err(Error::Protocol);
    }
    for (field, expected) in [
        ("assistant_message_id", &identity.assistant_message_id),
        ("chat_id", &identity.chat_id),
        ("turn_id", &identity.turn_id),
        ("job_id", &identity.job_id),
    ] {
        if value[field] != *expected {
            return Err(Error::Protocol);
        }
    }
    if value["key_version"] != identity.key_version
        || !value["content"].is_string()
        || ["category", "model_name"]
            .iter()
            .any(|field| !value[field].is_null() && !value[field].is_string())
    {
        return Err(Error::Protocol);
    }
    for field in ["thinking_content", "thinking_signature"] {
        if value.get(field).is_some_and(|value| !value.is_string()) {
            return Err(Error::Protocol);
        }
    }
    if value
        .get("has_thinking")
        .is_some_and(|value| !value.is_boolean())
        || value
            .get("thinking_token_count")
            .is_some_and(|value| value.as_u64().is_none())
        || value
            .get("thinking_duration_seconds")
            .is_some_and(|value| value.as_f64().is_none_or(|value| value < 0.0))
    {
        return Err(Error::Protocol);
    }
    Ok(())
}
pub(super) fn encrypt_main_assistant(
    recovered: &Value,
    identity: &crypto::RecoveryIdentity,
    created: u64,
    user_message: Option<&str>,
    key: &[u8; 32],
) -> Result<Value> {
    validate_main_plaintext(recovered, identity)?;
    let mut encrypted = json!({"client_message_id":identity.assistant_message_id,"chat_id":identity.chat_id,"role":"assistant","encrypted_content":crypto::encrypt_combined(recovered["content"].as_str().ok_or(Error::Protocol)?,key)?,"encrypted_sender_name":crypto::encrypt_combined("Assistant",key)?,"created_at":created,"updated_at":created});
    if let Some(user_message) = user_message {
        encrypted["user_message_id"] = json!(user_message)
    }
    for (field, target) in [
        ("category", "encrypted_category"),
        ("model_name", "encrypted_model_name"),
        ("thinking_content", "encrypted_thinking_content"),
        ("thinking_signature", "encrypted_thinking_signature"),
    ] {
        if let Some(value) = recovered.get(field).and_then(Value::as_str) {
            encrypted[target] = json!(crypto::encrypt_combined(value, key)?)
        }
    }
    Ok(encrypted)
}
fn metadata_aad(owner: &str, job: &CompletionRecoveryJob) -> Result<Vec<u8>> {
    let mut aad = b"OMCM1".to_vec();
    for value in [
        owner,
        job.chat_id.as_str(),
        job.task_id.as_deref().ok_or(Error::Protocol)?,
        job.job_id.as_str(),
    ] {
        canonical_uuid(value)?;
        aad.extend((value.len() as u32).to_be_bytes());
        aad.extend(value.as_bytes());
    }
    let stage = job.stage.as_deref().ok_or(Error::Protocol)?;
    if !matches!(stage, "initial" | "postprocessing") {
        return Err(Error::Protocol);
    }
    aad.extend((stage.len() as u32).to_be_bytes());
    aad.extend(stage.as_bytes());
    aad.extend(job.chat_key_version.to_be_bytes());
    Ok(aad)
}
fn metadata_field(field: &str) -> Result<&'static str> {
    match field {
        "title" => Ok("encrypted_title"),
        "summary" => Ok("encrypted_chat_summary"),
        "category" => Ok("encrypted_category"),
        "icon" => Ok("encrypted_icon"),
        _ => Err(Error::Protocol),
    }
}
fn decode_metadata_completion(
    claim: &Value,
    owner: &str,
    job: &CompletionRecoveryJob,
    key: &[u8; 32],
) -> Result<Value> {
    let serialized = required(claim, "sealed_payload")?;
    if serialized.len() > 100_000 {
        return Err(Error::Protocol);
    }
    let envelope: Value = serde_json::from_str(serialized)?;
    let pair = crypto::recovery_keypair(key, &job.chat_id, job.chat_key_version)?;
    let plain = crypto::open_recovery_with_aad(
        &envelope,
        &pair.private_key,
        &metadata_aad(owner, job)?,
        1,
        64 * 1024,
    )?;
    let mut value = Plain::new(serde_json::from_slice::<Value>(&plain)?);
    let identity = json!({"owner_id":owner,"chat_id":job.chat_id,"task_id":job.task_id,"job_id":job.job_id,"stage":job.stage,"key_version":job.chat_key_version});
    let object = value.as_object().ok_or(Error::Protocol)?;
    if object.len() != 7
        || identity
            .as_object()
            .ok_or(Error::Protocol)?
            .iter()
            .any(|(field, expected)| value[field] != *expected)
    {
        return Err(Error::Protocol);
    }
    let metadata = value["metadata"].as_object().ok_or(Error::Protocol)?;
    if metadata.is_empty()
        || metadata.iter().any(|(field, value)| {
            metadata_field(field).is_err() || value.as_str().is_none_or(|value| value.is_empty())
        })
    {
        return Err(Error::Protocol);
    }
    let declared = claim["encrypted_fields"]
        .as_array()
        .ok_or(Error::Protocol)?;
    let fields = metadata
        .keys()
        .map(|field| metadata_field(field).map(str::to_owned))
        .collect::<Result<std::collections::BTreeSet<_>>>()?;
    let actual = declared
        .iter()
        .map(|value| value.as_str().map(str::to_owned).ok_or(Error::Protocol))
        .collect::<Result<std::collections::BTreeSet<_>>>()?;
    if actual.len() != declared.len() || actual != fields {
        return Err(Error::Protocol);
    }
    Ok(std::mem::take(&mut value["metadata"]))
}
fn encrypt_metadata_fields(metadata: &Value, key: &[u8; 32]) -> Result<Value> {
    let mut encrypted = serde_json::Map::new();
    for (field, value) in metadata.as_object().ok_or(Error::Protocol)? {
        encrypted.insert(
            metadata_field(field)?.into(),
            json!(crypto::encrypt_combined(
                value.as_str().ok_or(Error::Protocol)?,
                key
            )?),
        );
    }
    if encrypted.is_empty() {
        return Err(Error::Protocol);
    }
    Ok(Value::Object(encrypted))
}
fn validate_checkpoint_candidate(
    checkpoint: &CompletionRecoveryCheckpoint,
    key: &[u8; 32],
    recovered: Option<&Value>,
) -> Result<()> {
    if checkpoint.protocol_version != 1 || checkpoint.job.chat_key_version != 1 {
        return Err(Error::Protocol);
    }
    let candidate = checkpoint
        .encrypted_candidate
        .as_object()
        .ok_or(Error::Protocol)?;
    if checkpoint.job.kind == CompletionRecoveryKind::Metadata {
        if checkpoint.team_id.is_some()
            || checkpoint.wrapped_chat_key.is_none()
            || candidate.is_empty()
        {
            return Err(Error::Forbidden);
        }
        let fields = [
            ("title", "encrypted_title"),
            ("summary", "encrypted_chat_summary"),
            ("category", "encrypted_category"),
            ("icon", "encrypted_icon"),
        ];
        for (field, cipher) in candidate {
            if !fields.iter().any(|(_, allowed)| field.as_str() == *allowed) {
                return Err(Error::Protocol);
            }
            let plain = zeroize::Zeroizing::new(crypto::decrypt_combined(
                cipher.as_str().ok_or(Error::Protocol)?,
                key,
            )?);
            if let Some(recovered) = recovered {
                let name = fields
                    .iter()
                    .find(|(_, encrypted)| *encrypted == field.as_str())
                    .ok_or(Error::Protocol)?
                    .0;
                if recovered[name] != plain.as_str() {
                    return Err(Error::Crypto);
                }
            }
        }
        if let Some(recovered) = recovered {
            if recovered.as_object().ok_or(Error::Protocol)?.len() != candidate.len() {
                return Err(Error::Protocol);
            }
        }
        return Ok(());
    }
    let allowed = [
        "client_message_id",
        "chat_id",
        "role",
        "encrypted_content",
        "encrypted_sender_name",
        "created_at",
        "updated_at",
        "encrypted_category",
        "encrypted_model_name",
        "encrypted_thinking_content",
        "encrypted_thinking_signature",
    ];
    if candidate
        .keys()
        .any(|field| !allowed.contains(&field.as_str()))
        || checkpoint.encrypted_candidate["client_message_id"].as_str()
            != checkpoint.job.assistant_message_id.as_deref()
        || checkpoint.encrypted_candidate["chat_id"] != checkpoint.job.chat_id
        || checkpoint.encrypted_candidate["role"] != "assistant"
        || checkpoint.encrypted_candidate["created_at"]
            .as_u64()
            .is_none()
        || checkpoint.encrypted_candidate["updated_at"]
            .as_u64()
            .is_none()
    {
        return Err(Error::Protocol);
    }
    let sender = zeroize::Zeroizing::new(crypto::decrypt_combined(
        required(&checkpoint.encrypted_candidate, "encrypted_sender_name")?,
        key,
    )?);
    if sender.is_empty() || !checkpoint.canonical_ciphertext && sender.as_str() != "Assistant" {
        return Err(Error::Crypto);
    }
    for (field, source) in [
        ("encrypted_content", "content"),
        ("encrypted_category", "category"),
        ("encrypted_model_name", "model_name"),
        ("encrypted_thinking_content", "thinking_content"),
        ("encrypted_thinking_signature", "thinking_signature"),
    ] {
        if let Some(cipher) = candidate.get(field) {
            let plain = zeroize::Zeroizing::new(crypto::decrypt_combined(
                cipher.as_str().ok_or(Error::Protocol)?,
                key,
            )?);
            if let Some(recovered) = recovered {
                if recovered[source] != plain.as_str() {
                    return Err(Error::Crypto);
                }
            }
        } else if field == "encrypted_content"
            || recovered.is_some_and(|recovered| recovered[source].is_string())
        {
            return Err(Error::Protocol);
        }
    }
    Ok(())
}
fn merge_metadata_receipt(receipt: &Value, current: &Value) -> Result<Value> {
    let versions = receipt["versions"].as_object().ok_or(Error::Protocol)?;
    if versions.len() != 2 {
        return Err(Error::Protocol);
    }
    let metadata = receipt["versions"]["metadata_v"]
        .as_u64()
        .ok_or(Error::Protocol)?;
    let title = receipt["versions"]["title_v"]
        .as_u64()
        .ok_or(Error::Protocol)?;
    let old_metadata = current["metadata_v"].as_u64().ok_or(Error::Protocol)?;
    let old_title = current["title_v"].as_u64().ok_or(Error::Protocol)?;
    let fields = receipt["encrypted_metadata"]
        .as_object()
        .ok_or(Error::Protocol)?;
    if fields.iter().any(|(field, value)| {
        ![
            "encrypted_title",
            "encrypted_chat_summary",
            "encrypted_category",
            "encrypted_icon",
        ]
        .contains(&field.as_str())
            || !value.is_string()
    }) {
        return Err(Error::Protocol);
    }
    let mut updated = current.clone();
    if metadata >= old_metadata {
        for (field, value) in fields {
            if field != "encrypted_title" || title >= old_title {
                updated[field] = value.clone();
            }
        }
        updated["metadata_v"] = json!(metadata);
        updated["title_v"] = json!(title.max(old_title));
    }
    Ok(updated)
}
fn metadata_receipt(
    job: &CompletionRecoveryJob,
    receipt: &Value,
    current: &Value,
) -> Result<CompletionRecoveryReceipt> {
    let mut metadata_version = current["metadata_v"].as_u64().ok_or(Error::Protocol)?;
    let mut title_version = current["title_v"].as_u64().ok_or(Error::Protocol)?;
    if let Some(versions) = receipt.get("versions") {
        let object = versions.as_object().ok_or(Error::Protocol)?;
        if object.len() != 2 {
            return Err(Error::Protocol);
        }
        metadata_version =
            metadata_version.max(versions["metadata_v"].as_u64().ok_or(Error::Protocol)?);
        title_version = title_version.max(versions["title_v"].as_u64().ok_or(Error::Protocol)?);
        let fields = receipt["encrypted_metadata"]
            .as_object()
            .ok_or(Error::Protocol)?;
        if fields.iter().any(|(field, value)| {
            ![
                "encrypted_title",
                "encrypted_chat_summary",
                "encrypted_category",
                "encrypted_icon",
            ]
            .contains(&field.as_str())
                || !value.is_string()
        }) {
            return Err(Error::Protocol);
        }
    }
    Ok(CompletionRecoveryReceipt {
        job_id: job.job_id.clone(),
        chat_id: job.chat_id.clone(),
        assistant_message_id: None,
        messages_version: None,
        metadata_version: Some(metadata_version),
        title_version: Some(title_version),
        state: required(receipt, "state")?.into(),
    })
}
fn iso_timestamp_ms(value: &str) -> Result<u64> {
    // Directus JS Date.toJSON emits exactly this UTC millisecond form.
    if value.len() != 24
        || [4, 7, 10, 13, 16, 19, 23].iter().any(|index| {
            value.as_bytes()[*index]
                != match index {
                    4 | 7 => b'-',
                    10 => b'T',
                    13 | 16 => b':',
                    19 => b'.',
                    _ => b'Z',
                }
        })
    {
        return Err(Error::Protocol);
    }
    let number = |start, end| {
        value
            .get(start..end)
            .filter(|value| value.bytes().all(|b| b.is_ascii_digit()))
            .and_then(|value| value.parse::<u64>().ok())
            .ok_or(Error::Protocol)
    };
    let (year, month, day, hour, minute, second, millis) = (
        number(0, 4)?,
        number(5, 7)?,
        number(8, 10)?,
        number(11, 13)?,
        number(14, 16)?,
        number(17, 19)?,
        number(20, 23)?,
    );
    let leap = |year: u64| year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    let days_in_month = [
        31,
        if leap(year) { 29 } else { 28 },
        31,
        30,
        31,
        30,
        31,
        31,
        30,
        31,
        30,
        31,
    ];
    if year < 1970
        || !(1..=12).contains(&month)
        || day == 0
        || day > days_in_month[(month - 1) as usize]
        || hour > 23
        || minute > 59
        || second > 59
    {
        return Err(Error::Protocol);
    }
    let leaps = |year: u64| year / 4 - year / 100 + year / 400;
    let days = (year - 1970) * 365 + leaps(year - 1) - leaps(1969)
        + days_in_month[..(month - 1) as usize].iter().sum::<u64>()
        + day
        - 1;
    Ok((((days * 24 + hour) * 60 + minute) * 60 + second) * 1000 + millis)
}
