        if !fence.valid()
            || self.operation_cancel.is_cancelled()
            || !Arc::ptr_eq(&self.task_watch_authority, &fence.owner)
            || self.generation != fence.generation
            || self.team()? != fence.team.as_deref()
        {
            return Err(Error::Cancelled);
        }
        Ok(())
    }
