            || path.starts_with("//")
            || path.contains('\\')
            || path.contains('#')
        {
            return Err(Error::Protocol);
        }
        let url = self.base.join(path).map_err(|_| Error::Protocol)?;
        if url.origin() != self.base.origin() {
            return Err(Error::Forbidden);
        }
        Ok(url)
    }
