    fn fixture(base:&str)->Client {
        let mut client=Client::new(base,Some(Session{api_url:base.into(),session_id:"fixture".into(),
            cookies:BTreeMap::new(),ws_token:None,master_key:zeroize::Zeroizing::new([7;32]),hashed_email:"fixture".into(),user_email_salt:String::new(),
            email_encryption_key:None,created_at:1,paired_session_expires_at:None,active_team_id:None})).expect("fixture");
        client.user=json!({"id":"11111111-1111-4111-8111-111111111111"});client
    }
    // Real loopback response, not an injected registry edge or fake receipt.
    // The shared merge is also the ordinary transport header boundary. Fixed
    // owned routes correctly reject principal drift before reaching this merge.
    async fn headers<F:Fn()->Result<()>>(client:&Client,listener:tokio::net::TcpListener,negative:F)->(OwnedReadHeaders,tokio::task::JoinHandle<()>) {
        let server=tokio::spawn(async move{
            let(mut stream,_)=listener.accept().await.expect("original request");let mut request=Vec::new();
            loop{let mut bytes=[0u8;1024];let read=stream.read(&mut bytes).await.expect("request bytes");assert!(read>0);request.extend_from_slice(&bytes[..read]);if request.windows(4).any(|part|part==b"\r\n\r\n"){break;}assert!(request.len()<8192);}
            assert!(String::from_utf8_lossy(&request).starts_with("GET /v1/tasks/fixture-task "));
            stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nSet-Cookie: auth_refresh_token=rotated; Path=/\r\nContent-Length: 11\r\nConnection: close\r\n\r\n{\"ok\":true}").await.expect("actual response");
        });
        let prepared=client.prepare_owned_read(OwnedReadRoute::AppTask("fixture-task")).expect("original fixed request");
        let cancel=CancellationToken::new();
        let received=send_owned_read_headers(prepared,&cancel,negative).await.expect("actual received response");
        (received,server)
    }
    async fn bound_fixture()->(Client,tokio::net::TcpListener) {
        let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.expect("fixture port");
        let client=fixture(&format!("http://{}",listener.local_addr().expect("fixture address")));
        (client,listener)
    }
    // contract-test: supporting surface=sdks.rust assertions=sdk.surface.semantic-parity,auth.session.isolation
    #[tokio::test]
    async fn actual_changed_headers_with_unreadable_binding_revoke_both_original_observers_permanently() {
        let(mut client,listener)=bound_fixture().await;
        let a=OwnedOperationScope::capture(&client,CancellationToken::new()).expect("A");
        let b=OwnedOperationScope::capture(&client,CancellationToken::new()).expect("B");
        let parent=client.operation_parent.clone();let generation=client.generation;
        let(received,server)=headers(&client,listener,||b.observer().check_release()).await;client.user=Value::Null;
        assert!(client.fresh_auth_binding().is_err(),"unreadable original owner binding");
        assert!(client.apply_owned_response_cookies(received.response.headers(),generation).is_err());
        assert_eq!(client.cookies.get("auth_refresh_token").map(String::as_str),Some("rotated"),"actual rotation must never roll back");
        assert!(a.observer().check_release().is_err());assert!(b.observer().check_release().is_err());
        client.user=json!({"id":"11111111-1111-4111-8111-111111111111"});
        assert!(a.observer().check_release().is_err());assert!(b.observer().check_release().is_err());
        assert!(a.check(&client).is_err());assert!(b.check(&client).is_err());assert_eq!(client.operation_parent,parent);
        server.await.expect("fixture server");
    }
    // contract-test: supporting surface=sdks.rust assertions=sdk.surface.semantic-parity,auth.session.isolation
    #[tokio::test]
    async fn actual_changed_headers_with_unreadable_binding_and_truly_empty_registry_keep_ordinary_rotation() {
        let(mut client,listener)=bound_fixture().await;let generation=client.generation;
        let(received,server)=headers(&client,listener,||Ok(())).await;client.user=Value::Null;
        assert!(client.fresh_auth_binding().is_err());
        assert!(client.apply_owned_response_cookies(received.response.headers(),generation).expect("ordinary empty registry").is_none());
        assert_eq!(client.cookies.get("auth_refresh_token").map(String::as_str),Some("rotated"));
        assert_eq!(client.session.as_ref().expect("session").cookies.get("auth_refresh_token").map(String::as_str),Some("rotated"));
        assert!(client.fresh_auth_binding().is_err(),"a real cookie merge grants no missing owner/read authority");
        server.await.expect("fixture server");
    }
}

//! Read-only API-key draft facade. Drafts belong to the authenticated account;
//! there is intentionally no owner/team override or project-grant fallback.
use crate::sdk::OpenMates;
use crate::{Error, Result, crypto};
use reqwest::Method;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::HashSet;

/// Ciphertext can be fetched without a local setup/decryption suffix.
/// Deliberately omits Debug to avoid accidental private-data logging.
#[derive(Clone, Serialize, Deserialize)]
pub struct EncryptedDraftRecord {
    pub chat_id: String,
    pub encrypted_draft_md: String,
    pub encrypted_draft_preview: Option<String>,
    pub draft_v: u64,
}

#[derive(Clone, Serialize, Deserialize)]
pub struct DraftRecord {
    #[serde(flatten)]
    pub encrypted: EncryptedDraftRecord,
    pub markdown: String,
    pub preview: Option<String>,
}

pub struct Drafts<'a> {
    client: &'a mut OpenMates,
}

impl<'a> Drafts<'a> {
    pub(super) fn new(client: &'a mut OpenMates) -> Self {
        Self { client }
    }

    /// Fetch only ciphertext. Backend enforces chat:read_existing and owner scope.
    pub async fn list_encrypted(&self) -> Result<Vec<EncryptedDraftRecord>> {
        self.authorize()?;
        let response = self
            .client
            .task_request(Method::GET, "/v1/sdk/drafts", None, false, None)
            .await?;
        parse_list(&response)
    }

    /// Decrypt locally using this explicit API key's account master-key wrapper.
    /// Project/team resource grants never substitute for the account master key.
    pub async fn list(&mut self) -> Result<Vec<DraftRecord>> {
        let encrypted = self.list_encrypted().await?;
        // Empty lists need no key unwrap (matching the other direct SDKs).
        if encrypted.is_empty() {
            return Ok(Vec::new());
        }
        let key = self.client.master_key().await?;
        encrypted
            .into_iter()
            .map(|draft| draft.decrypt(&key))
            .collect()
    }

    pub async fn get_encrypted(&self, chat_id: &str) -> Result<Option<EncryptedDraftRecord>> {
        self.authorize()?;
        if !crate::sdk::identifier(chat_id) {
            return Err(Error::Invalid(
                "Supply a chat identifier of 1–128 letters, digits, underscores or hyphens.",
            ));
        }
        let response = self
            .client
            .task_request(
                Method::GET,
                &format!("/v1/sdk/drafts/{chat_id}"),
                None,
                false,
                None,
            )
            .await?;
        parse_get(&response, chat_id)
    }

    pub async fn get(&mut self, chat_id: &str) -> Result<Option<DraftRecord>> {
        let Some(encrypted) = self.get_encrypted(chat_id).await? else {
            return Ok(None);
        };
        encrypted
            .decrypt(&*self.client.master_key().await?)
            .map(Some)
    }

    fn authorize(&self) -> Result<()> {
        if self.client.is_anonymous() {
            return Err(Error::Authentication);
        }
        self.client.verify_private_operation()
    }
}

impl EncryptedDraftRecord {
    /// Pure local operation for explicit caller-supplied account keys. No IO.
    pub fn decrypt(self, master_key: &[u8; 32]) -> Result<DraftRecord> {
        let markdown = crypto::decrypt_combined(&self.encrypted_draft_md, master_key)?;
        // A supplied but unauthenticatable preview is absent, never replaced
        // with markdown. This preserves the existing npm/Python SDK contract.
        let preview = match self.encrypted_draft_preview.as_deref() {
            Some(encrypted) => crypto::decrypt_combined(encrypted, master_key).ok(),
            None => Some(markdown.chars().take(160).collect()),
        };
        Ok(DraftRecord {
            encrypted: self,
            markdown,
            preview,
        })
    }
}

fn parse_record(value: &Value) -> Result<EncryptedDraftRecord> {
    if !value.is_object() {
        return Err(Error::Protocol);
    }
    let draft: EncryptedDraftRecord =
        serde_json::from_value(value.clone()).map_err(|_| Error::Protocol)?;
    if !crate::sdk::identifier(&draft.chat_id) || draft.encrypted_draft_md.is_empty() {
        return Err(Error::Protocol);
    }
    Ok(draft)
}

fn parse_list(response: &Value) -> Result<Vec<EncryptedDraftRecord>> {
    let rows = response
        .get("drafts")
        .and_then(Value::as_array)
        .ok_or(Error::Protocol)?;
    let mut ids = HashSet::new();
    rows.iter()
        .map(|row| {
            let draft = parse_record(row)?;
            if !ids.insert(draft.chat_id.clone()) {
                return Err(Error::Protocol);
            }
            Ok(draft)
        })
        .collect()
}

fn parse_get(response: &Value, expected_chat: &str) -> Result<Option<EncryptedDraftRecord>> {
    let value = response.get("draft").ok_or(Error::Protocol)?;
    if value.is_null() {
        return Ok(None);
    }
    let draft = parse_record(value)?;
    if draft.chat_id != expected_chat {
        return Err(Error::Protocol);
    }
    Ok(Some(draft))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn fixture() -> Value {
        serde_json::from_str::<Value>(include_str!("../tests/fixtures/sdk-api-key-drafts.json"))
            .unwrap()["capabilities"]["sdk.drafts"]
            .clone()
    }

    #[test]
    fn shared_draft_vectors_authenticate_locally_and_keep_ciphertext() {
        let fixture = fixture();
        let key = crypto::decode_key(fixture["key_b64"].as_str().unwrap()).unwrap();
        for vector in fixture["vectors"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|v| v["kind"] == "record")
        {
            let draft = parse_record(&vector["draft"]).unwrap();
            let cipher = draft.encrypted_draft_md.clone();
            let draft = draft.decrypt(&key).unwrap();
            assert_eq!(draft.markdown, vector["markdown"].as_str().unwrap());
            assert_eq!(draft.preview.as_deref(), vector["preview"].as_str());
            assert_eq!(draft.encrypted.encrypted_draft_md, cipher);
            let mut wrong = *key;
            wrong[0] ^= 1;
            assert!(
                parse_record(&vector["draft"])
                    .unwrap()
                    .decrypt(&wrong)
                    .is_err()
            );
            let mut broken = vector["draft"].clone();
            broken["encrypted_draft_md"] = json!("invalid-ciphertext");
            assert!(parse_record(&broken).unwrap().decrypt(&key).is_err());
        }
    }

    #[test]
    fn absent_drafts_are_authoritative_and_cross_chat_substitution_is_rejected() {
        assert!(
            parse_get(&json!({"draft": null}), "chat-1")
                .unwrap()
                .is_none()
        );
        assert!(parse_list(&json!({"drafts": []})).unwrap().is_empty());
        let draft = fixture()["vectors"][0]["draft"].clone();
        assert!(parse_get(&json!({"draft": draft}), "different-chat").is_err());
        assert!(parse_list(&json!({"drafts": [draft.clone(), draft]})).is_err());
        for value in [
            json!({}),
            json!({"drafts": null}),
            json!({"drafts": [null]}),
        ] {
            assert!(parse_list(&value).is_err());
        }
        for value in [json!({}), json!({"draft": []})] {
            assert!(parse_get(&value, "chat-1").is_err());
        }
    }

    #[test]
    fn malformed_records_fail_closed() {
        let draft = fixture()["vectors"][0]["draft"].clone();
        for (name, value) in [
            ("draft_v", json!(-1)),
            ("draft_v", json!(1.5)),
            ("chat_id", json!("../other")),
            ("encrypted_draft_md", json!("")),
            ("encrypted_draft_preview", json!({})),
        ] {
            let mut broken = draft.clone();
            broken[name] = value;
            assert!(parse_record(&broken).is_err());
        }
    }

    #[tokio::test]
